def gen(rng):
    from collections import deque

    def build(n, mode, lo=-1000, hi=1000):
        val = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if mode == 'left':
            slots = [(0, 1), (0, 0)]
        else:
            slots = [(0, 0), (0, 1)]
        if mode == 'bfs':
            slots = deque(slots)
        for v in range(1, n):
            if mode == 'zig':
                p, s = v - 1, v % 2
            else:
                if mode == 'rand':
                    i = rng.randrange(len(slots))
                    slots[i], slots[-1] = slots[-1], slots[i]
                    p, s = slots.pop()
                elif mode == 'deep':
                    i = rng.randrange(max(0, len(slots) - 2), len(slots))
                    slots[i], slots[-1] = slots[-1], slots[i]
                    p, s = slots.pop()
                elif mode == 'left':
                    p, s = slots.pop()
                else:
                    p, s = slots.popleft()
                if mode == 'left':
                    slots.append((v, 1))
                    slots.append((v, 0))
                else:
                    slots.append((v, 0))
                    slots.append((v, 1))
            if s == 0:
                L[p] = v
            else:
                R[p] = v
        toks = [str(val[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (L[u], R[u]):
                if c < 0:
                    toks.append('null')
                else:
                    toks.append(str(val[c]))
                    q.append(c)
        while toks and toks[-1] == 'null':
            toks.pop()
        return ' '.join(toks)

    tests = ['5', '-1000', '1 2', '1 null 2', '1 2 null 3', '1 null 2 null 3', '3 9 20 null null 15 7', '0 0 0 0 0 0 0']
    for n in range(1, 26):
        for mode in ('rand', 'deep'):
            tests.append(build(n, mode, -9, 9))
    tests.append(build(30, 'left', -9, 9))
    tests.append(build(30, 'zig', -9, 9))
    tests.append(build(1000, 'rand'))
    tests.append(build(100000, 'rand'))
    tests.append(build(100000, 'left'))
    tests.append(build(100000, 'zig'))
    tests.append(build(100000, 'bfs'))
    return tests
